@include('front.partials.cms-footer')<script>(()=>{const slides=[...document.querySelectorAll('.hero-slide')],dots=[...document.querySelectorAll('.slider-dot')];if(slides.length<2)return;let current=0,timer;const show=i=>{current=(i+slides.length)%slides.length;slides.forEach((s,n)=>{s.classList.toggle('active',n===current);s.setAttribute('aria-hidden',n===current?'false':'true')});dots.forEach((d,n)=>d.classList.toggle('active',n===current));clearInterval(timer);timer=setInterval(()=>show(current+1),6500)};dots.forEach(d=>d.onclick=()=>show(+d.dataset.slide));document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>show(current+(+b.dataset.direction)));show(0)})();</script></body></html>
